-module(arizona_test_server).
-export([start/0, stop/0, routes/0]).
-export([start_listener/0]).

start() ->
    %% The session fixtures (arizona_session_view/controller) encrypt the az_session
    %% cookie via arizona_crypto, which needs a signing key. The other fetch fixtures
    %% set plain cookies and don't read it.
    ok = application:set_env(arizona, secret_key, <<"e2e-test-secret-key-0123456789ab">>),
    %% Owned by this long-lived process: the fetch-repeat controller counts there.
    ok = arizona_fetch_repeat_controller:init(),
    %% A page with no server behind it: generated by arizona_static and served as a
    %% plain file under /static-site, where only the static client runs it.
    {[_Index], []} = arizona_static:generate(
        static_site_dir(),
        [{arizona_local, ~"index.html"}],
        #{layouts => [{arizona_static_layout, render}]}
    ),
    {ok, _} = start_listener(),
    %% Set the server app env *after* the listener is up (arizona_app has already
    %% booted, so this won't double-start a server) so the dev MCP server's
    %% `list_routes` tool can read the live routes.
    ok = application:set_env(arizona, server, #{
        adapter => arizona_roadrunner_server, routes => routes()
    }),
    ok.

%% The rich HTML dev error page is opt-in; the crash e2e specs assert on it.
%% Exposed so the outage fixture (arizona_outage_admin) can bring it back up.
start_listener() ->
    arizona_roadrunner_server:start(http, #{
        transport_opts => [{port, {env, "PORT", 4040}}],
        routes => routes(),
        error_page => {arizona_error_page, render}
    }).

%% The dev server's routes. Exposed so the dev MCP server's `list_routes` tool
%% can introspect them (see arizona_dev_mcp).
routes() ->
    Layouts = [{arizona_layout, render}],
    [
        {live, <<"/">>, arizona_page, #{
            bindings => #{title => <<"Welcome">>},
            layouts => Layouts
        }},
        {live, <<"/about">>, arizona_about, #{
            bindings => #{title => <<"About">>},
            layouts => Layouts
        }},
        {live, <<"/datatable">>, arizona_datatable, #{
            bindings => #{title => <<"DataTable">>},
            layouts => Layouts
        }},
        {live, <<"/stream-positions">>, arizona_stream_positions_page, #{
            bindings => #{title => <<"StreamPositions">>},
            layouts => Layouts
        }},
        {live, <<"/stream-siblings">>, arizona_stream_siblings_page, #{
            bindings => #{title => <<"StreamSiblings">>},
            layouts => Layouts
        }},
        {live, <<"/nodiff-widget">>, arizona_nodiff_widget, #{
            bindings => #{title => <<"NodiffWidget">>},
            layouts => Layouts
        }},
        {live, <<"/nodiff-widget-list">>, arizona_nodiff_widget_list, #{
            bindings => #{title => <<"NodiffWidgetList">>},
            layouts => Layouts
        }},
        {live, <<"/nodiff-widget-list-keyed">>, arizona_nodiff_widget_list, #{
            bindings => #{title => <<"NodiffWidgetListKeyed">>, keyed => true},
            layouts => Layouts
        }},
        {live, <<"/svg-each">>, arizona_svg_each_page, #{
            bindings => #{title => <<"SvgEach">>},
            layouts => Layouts
        }},
        {live, <<"/mixed">>, arizona_mixed_children, #{
            bindings => #{title => <<"Mixed">>},
            layouts => Layouts
        }},
        {live, <<"/inline">>, arizona_inline, #{
            bindings => #{title => <<"Inline">>},
            layouts => Layouts
        }},
        {live, <<"/rawtext">>, arizona_rawtext, #{
            bindings => #{title => <<"RawText">>},
            layouts => Layouts
        }},
        {live, <<"/controls">>, arizona_controls, #{
            bindings => #{title => <<"Controls">>},
            layouts => Layouts
        }},
        %% The server-owned controls fixture the az-ctl parity e2e drives.
        {live, <<"/ctl-parity">>, arizona_ctl_parity, #{
            bindings => #{title => <<"Ctl parity">>},
            layouts => Layouts,
            middlewares => [arizona_middleware:extract([params])]
        }},
        {live, <<"/select-value">>, arizona_select_value_page, #{
            bindings => #{title => <<"Select value">>},
            layouts => Layouts
        }},
        %% Room-scoped: the pubsub channel is `{chat, Room}`, so each e2e test
        %% gets a private channel on the long-lived shared test server.
        {live, <<"/chat/:room">>, arizona_chat, #{
            bindings => #{title => <<"Chat">>},
            layouts => Layouts,
            middlewares => [arizona_middleware:extract([path_bindings])]
        }},
        {live, <<"/local">>, arizona_local, #{
            bindings => #{title => <<"Local">>},
            layouts => Layouts
        }},
        {live, <<"/local-nested">>, arizona_local_nested, #{
            bindings => #{title => <<"Nested">>},
            layouts => Layouts
        }},
        {live, <<"/local-app">>, arizona_local_app, #{
            bindings => #{title => <<"App">>},
            layouts => Layouts
        }},
        %% Native-shell (OS) capability seam e2e -- a fake window.__arizona_os__
        %% (the Electron-preload equivalent) drives capability negotiation,
        %% server/client OS commands, and inbound OS events.
        {live, <<"/os">>, arizona_os_demo, #{
            bindings => #{title => <<"OS">>},
            layouts => Layouts
        }},
        {live, <<"/pip">>, arizona_pip, #{
            bindings => #{id => ~"pip_demo", title => <<"PiP">>},
            layouts => Layouts
        }},
        {live, <<"/pip-parent">>, arizona_pip_parent, #{
            bindings => #{title => <<"PiP parent">>},
            layouts => Layouts
        }},
        {live, <<"/events">>, arizona_events_demo, #{
            bindings => #{title => <<"Events">>},
            layouts => Layouts
        }},
        %% Static values under az-* names no template proves: data, never run.
        {live, <<"/unproven">>, arizona_unproven_data, #{
            bindings => #{title => <<"Unproven">>},
            layouts => Layouts
        }},
        %% Render-time az-* delivery: opaque dynamic commands (observed at
        %% mount / on a later frame's branch render) and a runtime-bound
        %% ?stateful(?get(page), ...) child (module observed at instantiation).
        {live, <<"/opaque-events">>, arizona_opaque_events, #{
            bindings => #{title => <<"Opaque">>},
            layouts => Layouts
        }},
        {live, <<"/dyn-page">>, arizona_dyn_page, #{layouts => Layouts}},
        %% A layout-declared effect attribute: deliverable only through the
        %% connect walk taking layout modules as roots (layouts render once,
        %% at SSR -- no frame can carry their markup).
        {live, <<"/layout-events">>, arizona_events_demo, #{
            bindings => #{title => <<"LayoutEvents">>},
            layouts => [{arizona_event_layout, render}]
        }},
        {live, <<"/transitions">>, arizona_transitions, #{
            bindings => #{title => <<"Transitions">>},
            layouts => Layouts
        }},
        %% In-place SPA navigation (az-patch) demo: az-patch links switch the
        %% :section while a chrome-owned counter survives (the view isn't
        %% remounted). Two routes sharing arizona_patch_demo -> same-handler patch.
        {live, <<"/patch-demo/:section">>, arizona_patch_demo, #{
            bindings => #{title => <<"Patch demo">>},
            middlewares => [arizona_middleware:extract([path_bindings])],
            layouts => Layouts
        }},
        {live, <<"/transitions/detail">>, arizona_transitions_detail, #{
            bindings => #{title => <<"Transition detail">>},
            layouts => Layouts
        }},
        {live, <<"/crashable">>, arizona_crashable, #{
            layouts => Layouts,
            middlewares => [arizona_middleware:extract([params])]
        }},
        {live, <<"/crash-on-connect">>, arizona_crashable, #{
            bindings => #{crash_on_connect => true},
            layouts => Layouts
        }},
        {live, <<"/scroll-home">>, arizona_scroll_home, #{layouts => Layouts}},
        {live, <<"/scroll-about">>, arizona_scroll_about, #{layouts => Layouts}},
        %% Same page, another layout list: an SPA navigate here degrades to a full load.
        {live, <<"/scroll-section">>, arizona_scroll_about, #{
            layouts => Layouts ++ [{arizona_scroll_layout, render}]
        }},
        {live, <<"/navigate-halt">>, arizona_navigate_halt, #{layouts => Layouts}},
        %% A middleware that halts with no redirect: HTTP answers 403, and an SPA
        %% navigate here becomes a full navigation that loads that response.
        {live, <<"/forbidden">>, arizona_navigate_halt, #{
            layouts => Layouts,
            middlewares => [fun(Req, _B) -> {halt, Req} end]
        }},
        {live, <<"/login">>, arizona_login, #{
            layouts => Layouts,
            middlewares => [{arizona_middleware, fetch_flash}]
        }},
        {live, <<"/protected">>, arizona_navigate_halt, #{
            layouts => Layouts,
            middlewares => [
                fun(Req, _B) ->
                    %% Set a flash, then halt with a redirect: over a WS navigate this
                    %% flash rides the socket to /login (no Set-Cookie leg) and is
                    %% shown there -- the flash-over-navigate round-trip end-to-end.
                    Req1 = arizona_req:put_flash(Req, error, <<"Please sign in first.">>),
                    {halt, arizona_req:redirect(Req1, <<"/login">>)}
                end
            ]
        }},
        {live, <<"/drainable">>, arizona_drainable, #{
            bindings => #{drain_mode => stop},
            layouts => Layouts
        }},
        {get, <<"/_test/drain">>, arizona_drain_admin, #{
            state => #{adapter => arizona_roadrunner_server}
        }},
        %% Fails its live mount (4501) while the `az_e2e_flaky` cookie is set.
        {live, <<"/flaky-mount">>, arizona_crashable, #{
            layouts => Layouts,
            middlewares => [fun flaky/2]
        }},
        %% A click here crashes the view (4500) and navigates to another view.
        {live, <<"/crash-nav">>, arizona_crash_nav, #{layouts => Layouts}},
        %% The same view (same id) under other layouts.
        {live, <<"/crash-nav-twin">>, arizona_crash_nav, #{
            layouts => Layouts ++ [{arizona_scroll_layout, render}]
        }},
        %% Crashes as a navigate unmounts it: the navigate is what crashes (4500).
        {live, <<"/crash-nav-leave">>, arizona_crash_nav, #{
            bindings => #{crash_on_leave => true, tall => true},
            layouts => Layouts
        }},
        %% A page whose load answers late (1.5 s).
        {live, <<"/crash-nav-slow">>, arizona_crash_nav, #{
            bindings => #{tall => true},
            layouts => Layouts,
            middlewares => [{arizona_crash_nav, slow}]
        }},
        %% Two pages that crash and navigate to each other on every connect.
        {live, <<"/crash-nav-ping">>, arizona_crash_nav, #{
            bindings => #{loop => true, other => <<"/crash-nav-pong">>},
            layouts => Layouts
        }},
        {live, <<"/crash-nav-pong">>, arizona_crash_nav, #{
            bindings => #{loop => true, other => <<"/crash-nav-ping">>},
            layouts => Layouts
        }},
        %% Two pages that navigate to each other on every connect, each crashing as
        %% the navigate unmounts it: every navigate fails over the socket and is
        %% answered with the load of its page, which works over HTTP.
        {live, <<"/crash-nav-bounce-a">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true, crash_on_leave => true, other => <<"/crash-nav-bounce-b">>
            },
            layouts => Layouts
        }},
        {live, <<"/crash-nav-bounce-b">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true, crash_on_leave => true, other => <<"/crash-nav-bounce-a">>
            },
            layouts => Layouts
        }},
        %% A wizard whose steps navigate to each other across layouts, on the user's
        %% click: every step is answered with a page load. `/wizard-q` shares the
        %% first step's layouts, so a navigate there is served live.
        {live, <<"/wizard-1">>, arizona_wizard, #{
            bindings => #{step => <<"1">>, other => <<"/wizard-2">>},
            layouts => Layouts
        }},
        {live, <<"/wizard-2">>, arizona_wizard, #{
            bindings => #{step => <<"2">>, other => <<"/wizard-1">>},
            layouts => Layouts ++ [{arizona_scroll_layout, render}]
        }},
        %% Patch on connect, the reply a full load inside a view transition: of
        %% `/transition-load` again (a loop), or of the page the patch asked for.
        {live, <<"/transition-load">>, arizona_transition_load, #{
            bindings => #{
                auto => true,
                patch => <<"/transition-load/p">>,
                target => <<"/transition-load">>
            },
            layouts => Layouts
        }},
        {live, <<"/transition-load/p">>, arizona_transition_load, #{layouts => Layouts}},
        {live, <<"/transition-own">>, arizona_transition_load, #{
            bindings => #{
                auto => true,
                patch => <<"/transition-own/p">>,
                target => <<"/transition-own/p">>
            },
            layouts => Layouts
        }},
        {live, <<"/transition-own/p">>, arizona_transition_load, #{layouts => Layouts}},
        %% Navigates to the next step on connect, then, 2 s later, to `/wizard-q`.
        {live, <<"/wizard-auto">>, arizona_wizard, #{
            bindings => #{step => <<"auto">>, other => <<"/wizard-2">>, auto => true},
            layouts => Layouts
        }},
        %% A hop the user reaches live from `/wizard-1`, whose view then navigates
        %% across layouts to the next step on its own.
        {live, <<"/wizard-r">>, arizona_wizard, #{
            bindings => #{step => <<"r">>, other => <<"/wizard-2">>, hop => true},
            layouts => Layouts
        }},
        {live, <<"/wizard-q">>, arizona_wizard, #{
            bindings => #{step => <<"q">>, other => <<"/wizard-2">>},
            layouts => Layouts
        }},
        %% The same loop, the page's own code sending an event first (no person).
        {live, <<"/crash-nav-ping-connected-a">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true,
                crash_on_leave => true,
                ping => <<"connected">>,
                other => <<"/crash-nav-ping-connected-b">>
            },
            layouts => Layouts
        }},
        {live, <<"/crash-nav-ping-connected-b">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true,
                crash_on_leave => true,
                ping => <<"connected">>,
                other => <<"/crash-nav-ping-connected-a">>
            },
            layouts => Layouts
        }},
        {live, <<"/crash-nav-ping-hooklater-a">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true,
                crash_on_leave => true,
                ping => <<"hooklater">>,
                other => <<"/crash-nav-ping-hooklater-b">>
            },
            layouts => Layouts
        }},
        {live, <<"/crash-nav-ping-hooklater-b">>, arizona_crash_nav, #{
            bindings => #{
                bounce => true,
                crash_on_leave => true,
                ping => <<"hooklater">>,
                other => <<"/crash-nav-ping-hooklater-a">>
            },
            layouts => Layouts
        }},
        %% Crashes and navigates to itself on every connect: a recurring crash.
        {live, <<"/crash-nav-loop">>, arizona_crash_nav, #{
            bindings => #{loop => true},
            layouts => Layouts
        }},
        %% A patch here to `?boom=1` crashes the view (4500); a fresh mount does not.
        {live, <<"/patch-crash">>, arizona_patch_crash, #{
            layouts => Layouts,
            middlewares => [arizona_middleware:extract([params])]
        }},
        %% A patch here answers with a navigate to a fragment of the patched page.
        {live, <<"/hash-patch">>, arizona_hash_patch, #{
            layouts => Layouts,
            middlewares => [arizona_middleware:extract([params])]
        }},
        %% Shows what `?reconnected` read at mount.
        {live, <<"/reconnect-probe">>, arizona_reconnect_probe, #{layouts => Layouts}},
        %% Stops the listener, then starts it again: a server outage and restart.
        {get, <<"/_test/outage">>, arizona_outage_admin, #{}},
        %% A page whose WebSocket upgrade halts while the `az_e2e_gate` cookie is
        %% set, while HTTP still answers: a proxy that does not upgrade, or one
        %% refused reconnect attempt.
        {live, <<"/upgrade-gate">>, arizona_about, #{
            bindings => #{title => <<"Gate">>},
            layouts => Layouts,
            middlewares => [fun gate/2]
        }},
        %% Dev-reload fixture: a JSON view holding a fun made by a module the
        %% admin endpoint reloads (e2e/sequential/arizona_reload.spec.js).
        {live, <<"/json/reload-fun">>, arizona_reload_fun_view, #{}},
        %% Two JSON pages that navigate to each other on connect, every navigate
        %% failing over the socket and answered with a full navigate.
        {live, <<"/json/bounce-a">>, arizona_json_bounce, #{
            bindings => #{other => <<"/json/bounce-b">>}
        }},
        {live, <<"/json/bounce-b">>, arizona_json_bounce, #{
            bindings => #{other => <<"/json/bounce-a">>}
        }},
        {get, <<"/_test/reload">>, arizona_reload_admin, #{}},
        %% arizona_js:fetch e2e -- a form posts to the controller (sets an HttpOnly
        %% cookie, broadcasts to the live view via pubsub, returns an effect); no reload.
        {live, <<"/fetch-account">>, arizona_fetch_account, #{
            bindings => #{title => <<"Account">>},
            layouts => Layouts
        }},
        {post, <<"/fetch-account/submit">>, arizona_fetch_account_controller, #{}},
        %% arizona_js:fetch on_repeat -- a slow endpoint counting requests per token, so a
        %% repeat lands while the first is in flight (drop vs the default allow).
        {live, <<"/fetch-repeat">>, arizona_fetch_repeat, #{
            bindings => #{title => <<"Repeat">>},
            layouts => Layouts
        }},
        {post, <<"/fetch-repeat/hit">>, arizona_fetch_repeat_controller, #{
            state => #{delay_ms => 300}
        }},
        {get, <<"/fetch-repeat/count">>, arizona_fetch_repeat_controller, #{action => count}},
        %% arizona_js:push_event on_repeat -- a slow handler, so a repeat is raised while
        %% the first event awaits its reply (drop vs the default allow).
        {live, <<"/push-repeat">>, arizona_push_repeat, #{
            bindings => #{title => <<"Push repeat">>, delay_ms => 300},
            layouts => Layouts
        }},
        %% arizona_js:fetch + push_event -- the controller's response push_event re-renders
        %% the submitting view via handle_event (no pubsub); for refreshing only that view.
        {live, <<"/fetch-push">>, arizona_fetch_push, #{
            bindings => #{title => <<"Push">>},
            layouts => Layouts
        }},
        {post, <<"/fetch-push/submit">>, arizona_fetch_push_controller, #{}},
        %% arizona_js:fetch + az-form-reset -- the reset waits for the 2xx, and keeps what
        %% the user typed while the request was in flight.
        {live, <<"/fetch-reset">>, arizona_fetch_reset, #{
            bindings => #{title => <<"Fetch reset">>},
            layouts => Layouts
        }},
        {post, <<"/fetch-reset/submit">>, arizona_fetch_reset_controller, #{}},
        %% reply_redirect/1 to a relative Location: the client resolves it against the
        %% endpoint's URL (`/scroll-home`), not the page that posted or its <base>.
        {post, <<"/fetch-redirect">>, arizona_fetch_redirect_controller, #{
            state => {redirect, <<"scroll-home">>}
        }},
        %% A response's SPA navigate/patch stays the page's: a fragment scrolls it, a
        %% query patches it -- neither names the endpoint.
        {post, <<"/fetch-effects/hash">>, arizona_fetch_redirect_controller, #{
            state => {effects, [arizona_js:navigate(<<"#hello">>)]}
        }},
        {post, <<"/fetch-effects/patch">>, arizona_fetch_redirect_controller, #{
            state => {effects, [arizona_js:patch(<<"?tab=2">>)]}
        }},
        %% Form-aware payload -- one az_submit push_event on a two-submit-button form; the
        %% payload carries the form's fields plus which named submit button fired.
        {live, <<"/form-submitter">>, arizona_form_submitter, #{
            bindings => #{title => <<"Form Submitter">>},
            layouts => Layouts
        }},
        %% arizona_js:fetch on_error -- the controller replies 500 with no effects body, so
        %% the client runs the fetch's on_error commands and fires arizona:fetch-error.
        {live, <<"/fetch-error">>, arizona_fetch_error, #{
            bindings => #{title => <<"Error">>},
            layouts => Layouts
        }},
        {post, <<"/fetch-error/submit">>, arizona_fetch_error_controller, #{}},
        %% arizona_session write loop -- a fetch posts to the controller, which rotates
        %% the encrypted az_session cookie and push_events the new name; fetch_session on
        %% the page route reads the persisted name back from the cookie on the next load.
        {live, <<"/session">>, arizona_session_view, #{
            bindings => #{title => <<"Session">>},
            layouts => Layouts,
            middlewares => [{arizona_middleware, fetch_session}]
        }},
        {post, <<"/session/save">>, arizona_session_controller, #{}},
        %% JSON view -- no layouts (JSON has no HTTP page); the first
        %% frame is mount_and_render over the WebSocket.
        {live, <<"/json/counter">>, arizona_json_counter_demo, #{}},
        {live, <<"/json/list">>, arizona_json_list, #{
            bindings => #{
                items => [
                    #{id => ~"1", text => ~"One"},
                    #{id => ~"2", text => ~"Two"},
                    #{id => ~"3", text => ~"Three"}
                ]
            }
        }},
        {live, <<"/json/tabs">>, arizona_json_tabs, #{}},
        {live, <<"/json/ticker">>, arizona_json_ticker, #{}},
        {live, <<"/json/multi">>, arizona_json_multi, #{}},
        {live, <<"/json/nested">>, arizona_json_nested, #{}},
        {live, <<"/json/removable">>, arizona_json_removable, #{}},
        {live, <<"/json/conditional">>, arizona_json_conditional, #{}},
        {live, <<"/json/stream-child">>, arizona_json_stream_child, #{}},
        {live, <<"/json/menu">>, arizona_json_menu, #{}},
        {ws, <<"/ws">>, #{}},
        {asset, <<"/priv">>, {priv_dir, arizona, "static/assets/js"}},
        {asset, <<"/static-site">>, {dir, static_site_dir()}},
        %% Dev-introspection MCP server (see arizona_dev_mcp); the helper defaults
        %% to session mode so eval is a persistent REPL. A CLI agent connects with
        %% no Origin; origins stays opt-in.
        arizona_dev_mcp:route(<<"/mcp">>)
    ].

stop() ->
    arizona_roadrunner_server:stop(http).

gate(Req0, Bindings) ->
    {Cookies, Req1} = arizona_req:cookies(Req0),
    {Headers, Req} = arizona_req:headers(Req1),
    Upgrade = string:lowercase(iolist_to_binary(maps:get(<<"upgrade">>, Headers, <<>>))),
    case {proplists:get_value(<<"az_e2e_gate">>, Cookies), Upgrade} of
        {undefined, _} -> {cont, Req, Bindings};
        {_, <<"websocket">>} -> {halt, arizona_req:redirect(Req, <<"/">>)};
        {_, _} -> {cont, Req, Bindings}
    end.

flaky(Req0, Bindings) ->
    {Cookies, Req} = arizona_req:cookies(Req0),
    Flaky = proplists:is_defined(<<"az_e2e_flaky">>, Cookies),
    {cont, Req, Bindings#{crash_on_connect => Flaky}}.

static_site_dir() ->
    filename:absname("_build/e2e-static").
